from urllib.parse import urlparse

def is_safe_url(url, allowed_domains=None):
    return all(
        urlparse(url).scheme in ('http', 'https') and
        (allowed_domains is None or urlparse(url).netloc in allowed_domains)
    )

if is_safe_url(target_url):
    return HttpResponseRedirect(target_url)
else:
    return HttpResponseRedirect('/')

